import{_ as t,o as d,c as r,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Filters","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/rules/filters.md","filePath":"en/docs/rules/filters.md"}'),c={name:"en/docs/rules/filters.md"};function i(a,e,l,n,s,p){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h1><p>When matching based on request or response attributes (not just the URL), you can use filters to achieve more granular rule control. The syntax is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pattern operator includeFilter://pattern1 ... excludeFilter://patternx ...</span></span></code></pre></div><blockquote><p>Multiple filters are matched &quot;or&quot;; as long as one of the filter conditions matches, the match is true.</p></blockquote><h2 id="filter-types" tabindex="-1">Filter Types <a class="header-anchor" href="#filter-types" aria-label="Permalink to &quot;Filter Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Filter Type</th><th>Syntax</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Include Filter</strong></td><td><code>includeFilter://pattern</code></td><td>Match only requests that match the specified conditions</td></tr><tr><td><strong>Exclude Filter</strong></td><td><code>excludeFilter://pattern</code></td><td>Exclude requests that match the specified conditions</td></tr></tbody></table><h2 id="pattern-types" tabindex="-1">Pattern Types <a class="header-anchor" href="#pattern-types" aria-label="Permalink to &quot;Pattern Types&quot;">​</a></h2><p>Match expressions used with <code>includeFilter://&lt;pattern&gt;</code> and <code>excludeFilter://&lt;pattern&gt;</code>.</p><blockquote><p><strong>General rules</strong></p><ul><li>When no prefix is specified, the request URL is matched by default.</li><li>Keyword matching is case-insensitive by default.</li><li>Regex format is <code>/regexp/</code>; append <code>i</code> at the end to ignore case, e.g. <code>/regexp/i</code>.</li><li>The <code>probability</code> value for <code>chance</code> ranges from <code>0</code> to <code>1</code>.</li></ul></blockquote><table tabindex="0"><thead><tr><th>Syntax</th><th>Match target</th><th>Example</th></tr></thead><tbody><tr><td><code>b:pattern</code></td><td>Request body content: keyword (case-insensitive) or regex</td><td><code>includeFilter://b:keyword</code><br><code>excludeFilter://b:/regexp/i</code></td></tr><tr><td><code>m:pattern</code></td><td>HTTP method: method name (case-insensitive) or regex</td><td><code>includeFilter://m:get</code><br><code>excludeFilter://m:/regexp/i</code></td></tr><tr><td><code>i:pattern</code></td><td>Client or server IP: IP or regex</td><td><code>includeFilter://i:192.168.1.10</code><br><code>excludeFilter://i:/regexp/i</code></td></tr><tr><td><code>chance:probability</code></td><td>Random hit by probability: <code>Math.random() &lt; probability</code></td><td><code>includeFilter://chance:0.5</code><br><code>excludeFilter://chance:0.3</code></td></tr><tr><td><code>clientIp:pattern</code></td><td>Client IP: IP or regex</td><td><code>includeFilter://clientIp:192.168.1.10</code><br><code>excludeFilter://clientIp:/regexp/i</code></td></tr><tr><td><code>serverIp:pattern</code></td><td>Server IP: IP or regex</td><td><code>includeFilter://serverIp:192.168.1.10</code><br><code>excludeFilter://serverIp:/regexp/i</code></td></tr><tr><td><code>s:pattern</code></td><td>Response status code: status code or regex</td><td><code>includeFilter://s:/^20/</code><br><code>excludeFilter://s:200</code></td></tr><tr><td><code>reqH.header-key:pattern</code></td><td>Request header: keyword (case-insensitive) or regex</td><td><code>includeFilter://reqH.content-type:json</code><br><code>excludeFilter://reqH.content-type:/regexp/i</code></td></tr><tr><td><code>resH.header-key:pattern</code></td><td>Response header: keyword (case-insensitive) or regex</td><td><code>includeFilter://resH.content-type:json</code><br><code>excludeFilter://resH.content-type:/regexp/i</code></td></tr><tr><td>No-prefix <code>pattern</code> (any other <code>xxxxxx</code>)</td><td>Request URL, same as <a href="./pattern.html">pattern</a></td><td><code>includeFilter://*/cgi-*</code><br><code>excludeFilter://www.test.com</code><br><code>includeFilter://https://www.test.com/path</code></td></tr></tbody></table>',10)])])}const x=t(c,[["render",i]]);export{u as __pageData,x as default};
